class Solution:
    def romanToInt(self, s):
        roman = {'I':1, 'V':5, 'X':10, 'L':50, 'C':100, 'D':500, 'M':1000}
        result = 0
        for i in range(len(s)):
            current = roman[s[i]]
            following = roman[s[i + 1]] if i + 1 < len(s) else 0
            subtract = current < following
            if subtract:
                result -= current
            else:
                result += current
        return result

