class Solution:
    def convertToTitle(self, columnNumber):
        n = columnNumber
        letters = []
        while n > 0:
            n -= 1
            digit = n % 26
            letter = chr(ord('A') + digit)
            letters.append(letter)
            n //= 26
        return ''.join(reversed(letters))

