class Solution:
    def countPrimes(self, n):
        if n < 2:
            return 0
        prime = [True] * n
        prime[0] = False
        prime[1] = False
        p = 2
        while p * p < n:
            if prime[p]:
                for multiple in range(p * p, n, p):
                    prime[multiple] = False
            p += 1
        count = 0
        for value in range(2, n):
            if prime[value]:
                count += 1
        return count
